<script setup>
import { Head, useForm, usePage } from "@inertiajs/vue3";
const props = defineProps({ departments: Array, items: Array, store_url: String, track_url: String });
const page = usePage();
const form = useForm({ applicant_name: "", applicant_nrp: "", applicant_phone: "", department_id: "", needed_at: "", purpose: "", lines: [{ item_id: "", quantity: 1 }] });
const tracking = useForm({ request_no: "", verifier: "" });
const add = () => form.lines.push({ item_id: "", quantity: 1 });
</script>
<template><Head title="Material Request"/><main class="public-request"><section class="public-request__hero"><p class="eyebrow">Warehouse Service</p><h1>Material Request</h1><p>Kirim kebutuhan barang dan pantau prosesnya tanpa akun.</p><div v-if="page.props.flash?.success" class="flash-message" role="status"><strong>{{ page.props.flash.success }}</strong></div></section><div class="public-request__grid"><form class="surface-card form-stack" @submit.prevent="form.post(store_url)"><h2>Buat permintaan</h2><div v-if="Object.keys(form.errors).length" class="field-error" role="alert"><p v-for="(error,key) in form.errors" :key="key">{{ error }}</p></div><label>Nama pemohon<input v-model="form.applicant_name" class="form-input" required/></label><div class="form-grid"><label>NRP<input v-model="form.applicant_nrp" class="form-input" required/></label><label>Nomor telepon<input v-model="form.applicant_phone" class="form-input" required/></label></div><label>Departemen<select v-model="form.department_id" class="form-input" required><option value="">Pilih departemen</option><option v-for="department in departments" :key="department.id" :value="department.id">{{ department.department_code }} · {{ department.department_name }}</option></select></label><p v-if="!departments.length" class="field-error">Departemen belum tersedia. Hubungi Admin.</p><label>Dibutuhkan pada<input v-model="form.needed_at" type="datetime-local" class="form-input" required/></label><label>Keperluan<textarea v-model="form.purpose" class="form-input" required/></label><fieldset><legend>Barang</legend><div v-for="(line,index) in form.lines" :key="index" class="form-grid"><select v-model="line.item_id" class="form-input" required><option value="">Pilih barang</option><option v-for="item in items" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }} ({{ item.ownership }})</option></select><input v-model="line.quantity" type="number" min="1" step="1" class="form-input" aria-label="Quantity" required/></div><button type="button" class="button button--secondary" @click="add">Tambah barang</button></fieldset><button class="button button--primary" :disabled="form.processing || !departments.length">Kirim MR</button></form><form class="surface-card form-stack" @submit.prevent="tracking.post(track_url)"><h2>Lacak MR</h2><p>Masukkan nomor MR dan NRP atau nomor telepon pemohon.</p><div v-if="tracking.errors.tracking" class="field-error" role="alert">{{ tracking.errors.tracking }}</div><label>Nomor MR<input v-model="tracking.request_no" class="form-input" placeholder="MR/20261030/0001" required/></label><label>NRP / telepon<input v-model="tracking.verifier" class="form-input" required/></label><button class="button button--secondary">Lihat status</button></form></div></main></template>
<style scoped>.public-request{min-height:100vh;padding:clamp(24px,5vw,72px);background:linear-gradient(145deg,#eef5ff,#f8fbff 55%,#e6f8fb)}.public-request__hero{max-width:760px;margin:0 auto 32px}.public-request__hero h1{font-size:clamp(2.2rem,5vw,4.5rem);margin:.25rem 0}.eyebrow{text-transform:uppercase;letter-spacing:.18em;color:#2563eb;font-weight:800}.public-request__grid{max-width:1180px;margin:auto;display:grid;grid-template-columns:minmax(0,2fr) minmax(280px,1fr);gap:24px;align-items:start}.surface-card{padding:clamp(20px,3vw,36px)}label{display:grid;gap:8px;font-weight:700}fieldset{border:1px solid #dbe5f2;border-radius:16px;padding:16px}.form-stack{display:grid;gap:18px}.flash-message{margin-top:20px}@media(max-width:800px){.public-request__grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}}</style>
